function makeId() { return Math.random().toString(36).substr(2, 9); }
function getDesc(n, r) { return (r ? REFURB_DESC : DEFAULT_DESC)[n] || ""; }
function makeItem(name, isRefurb, defaultCond) { const cond = defaultCond !== undefined ? defaultCond : (isRefurb ? 5 : 4); return { id: makeId(), name, description: getDesc(name, isRefurb), condition: cond }; }
function hasContent(item) { if (item.severity !== undefined && item.severity !== null) return true; if (item.meterData) return !!(item.meterData.location || item.meterData.serial || item.meterData.reading); if (item.boilerData) return !!(item.boilerData.location || item.boilerData.make); if (item.locationData) return !!item.locationData.location; if (item.fuseData) return !!(item.fuseData.location || item.fuseData.notes); return (item.description && item.description.trim() !== "") || item.condition > 0; }
function conditionLabel(n) { return ["","Poor","Below Average","Average","Good","Excellent -- little to no visible defects"][n] || ""; }

function buildRoomItems(key, opts) {
  const { isRefurb, isFurnished, heatingType, bathroomType } = opts;
  const heatingItem = heatingType === "gas" ? "Radiator" : "Heater";
  let items = [];
  if (key === "bathroom") {
    items = [...BATHROOM_BASE];
    if (bathroomType === "shower" || bathroomType === "both") items.push("Shower / Cubicle");
    if (bathroomType === "bath" || bathroomType === "both") items.push("Bath / Bath Panel");
    items = [...items, ...BATHROOM_END];
  } else {
    items = [...(ROOM_BASE[key] || [])];
    const fi = items.indexOf("Flooring");
    items = [...items.slice(0, fi), heatingItem, ...items.slice(fi)];
    if (isFurnished && (key === "lounge" || key === "kitchenLounge")) items = [...items, ...FURNITURE_LOUNGE];
  }
  const FLOORING_DESC = {
    entrance: "Laminate flooring", lounge: "Laminate flooring",
    kitchen: "Laminate flooring", kitchenLounge: "Laminate flooring",
    bedroom: "Carpeted flooring", bedroom_furnished: "Carpeted flooring",
    bathroom: "Waterproof LVT (vinyl tile)",
  };
  return items.map(n => {
    if (n === "Flooring") {
      const desc = FLOORING_DESC[key] || "Flooring";
      return { id: makeId(), name: n, description: desc, condition: isRefurb ? 5 : 4 };
    }
    return makeItem(n, isRefurb);
  });
}
function makeRoom(key, name, opts) {
  const nameMap = { entrance:"Entrance / Hallway",lounge:"Lounge",kitchen:"Kitchen",kitchenLounge:"Kitchen / Lounge",bedroom:"Bedroom",bedroom_furnished:"Bedroom",bathroom:"Bathroom" };
  return { id: makeId(), name: name || nameMap[key], items: buildRoomItems(key, opts), photos: [], notes: "" };
}
function makeCommunal(hasGarden, isRefurb) {
  const items = hasGarden ? [...COMMUNAL_BASE, "Garden / Grounds"] : [...COMMUNAL_BASE];
  return { id: makeId(), name: "Communal Areas & Building Exterior", items: items.map(n => makeItem(n, isRefurb)), photos: [], notes: "" };
}

