function Toggle({ value, onChange, label, sublabel }) {
  return (
    <div className="flex items-center justify-between px-4 py-4">
      <div><p className="text-sm font-semibold text-gray-800">{label}</p>{sublabel && <p className="text-xs text-gray-400">{sublabel}</p>}</div>
      <button onClick={() => onChange(!value)} className="w-12 h-6 rounded-full relative transition-all flex-shrink-0" style={{ background: value ? BRAND : "#d1d5db" }}>
        <div className="w-5 h-5 bg-white rounded-full absolute top-0.5 shadow transition-all" style={{ left: value ? "26px" : "2px" }} />
      </button>
    </div>
  );
}
function StarRating({ value, onChange }) {
  return (
    <div className="flex gap-1">
      {[1,2,3,4,5].map(s => (
        <button key={s} onClick={() => onChange(s === value ? 0 : s)} className="p-1 touch-manipulation">
          <Star size={26} fill={s <= value ? "#f59e0b" : "none"} color={s <= value ? "#f59e0b" : "#d1d5db"} />
        </button>
      ))}
    </div>
  );
}
function RoomPhotoSection({ photos, onUpdate }) {
  const id = useRef("photo-" + Math.random().toString(36).substr(2,6));
  const handleFiles = e => {
    const files = Array.from(e.target.files);
    files.forEach(file => { const r = new FileReader(); r.onload = ev => onUpdate(p => [...p, ev.target.result]); r.readAsDataURL(file); });
    e.target.value = "";
  };
  return (
    <div className="bg-white rounded-2xl border-2 border-dashed border-gray-300 p-5">
      <div className="flex items-center justify-between mb-4">
        <div><p className="text-sm font-semibold text-gray-800">Photos</p><p className="text-xs text-gray-400">{photos.length > 0 ? `${photos.length} photo${photos.length > 1 ? "s" : ""} added` : "Select multiple photos at once"}</p></div>
        <label htmlFor={id.current} className="flex items-center gap-2 text-sm font-semibold px-4 py-2.5 rounded-xl text-white touch-manipulation cursor-pointer" style={{ background: BRAND }}>
          <Image size={15} /> Add Photos
        </label>
      </div>
      {photos.length > 0 && (
        <div className="grid grid-cols-3 gap-2">
          {photos.map((photo, idx) => (
            <div key={idx} className="relative aspect-square rounded-xl overflow-hidden border-2 border-gray-200">
              <img src={photo} alt="" className="w-full h-full object-cover" />
              <button onClick={() => onUpdate(p => p.filter((_,i) => i !== idx))} className="absolute top-1 right-1 w-6 h-6 bg-red-500 rounded-full flex items-center justify-center shadow"><X size={10} className="text-white" /></button>
            </div>
          ))}
        </div>
      )}
      <input id={id.current} type="file" accept="image/*" multiple className="hidden" onChange={handleFiles} />
    </div>
  );
}
function ItemCard({ item, onChange, autoExpand }) {
  const [expanded, setExpanded] = useState(!!autoExpand);
  const [isRecording, setIsRecording] = useState(false);
  const recRef = useRef(null);
  const startDictation = () => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { alert("Speech recognition not supported."); return; }
    const r = new SR(); r.continuous = false; r.interimResults = false; r.lang = "en-GB";
    r.onresult = e => { onChange({ ...item, description: (item.description ? item.description + ". " : "") + e.results[0][0].transcript }); setIsRecording(false); };
    r.onerror = () => setIsRecording(false); r.onend = () => setIsRecording(false);
    r.start(); recRef.current = r; setIsRecording(true);
  };
  const stopDictation = () => { recRef.current?.stop(); setIsRecording(false); };
  const filled = hasContent(item);
  return (
    <div className="bg-white rounded-2xl border-2 overflow-hidden" style={{ borderColor: expanded ? BRAND : item.condition > 0 ? "#86efac" : "#e5e7eb", background: !expanded && item.condition > 0 ? "#f0fdf4" : "white" }}>
      <button className="w-full flex items-center justify-between px-4 py-3.5 touch-manipulation" onClick={() => setExpanded(!expanded)}>
        <div className="flex items-center gap-3">
          <div className="w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold flex-shrink-0" style={{ background: filled ? BRAND : "#f3f4f6", color: filled ? "white" : "#9ca3af" }}>{filled ? "v" : "-"}</div>
          <span className="text-sm font-semibold text-gray-800 text-left">{item.name}</span>
        </div>
        <div className="flex items-center gap-2">
          {item.condition > 0 && <span className="text-xs px-2 py-0.5 rounded-full text-white" style={{ background: BRAND }}>{item.condition}/5</span>}
          <ChevronRight size={16} className="text-gray-400" style={{ transform: expanded ? "rotate(90deg)" : "rotate(0deg)" }} />
        </div>
      </button>
      {expanded && (
        <div className="px-4 pb-5 pt-3 space-y-4 border-t border-gray-100">
          <div>
            <div className="flex items-center justify-between mb-1.5">
              <p className="text-xs font-semibold uppercase tracking-wider text-gray-400">Description</p>
              <button onPointerDown={startDictation} onPointerUp={stopDictation} className="flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-full border-2 transition-all select-none" style={{ borderColor: isRecording ? BRAND : "#e5e7eb", background: isRecording ? `${BRAND}15` : "white", color: isRecording ? BRAND : "#6b7280" }}>
                {isRecording ? <MicOff size={12} /> : <Mic size={12} />}{isRecording ? "Recording..." : "Dictate"}
              </button>
            </div>
            <textarea className="w-full border-2 border-gray-200 rounded-xl px-3 py-2.5 text-sm resize-none focus:outline-none" style={{ fontFamily: "Georgia, serif", minHeight: "72px" }} value={item.description} onChange={e => onChange({ ...item, description: e.target.value })} />
          </div>
          <div>
            <p className="text-xs font-semibold uppercase tracking-wider text-gray-400 mb-2">Condition</p>
            <div className="flex items-center gap-3 flex-wrap">
              <StarRating value={item.condition} onChange={v => onChange({ ...item, condition: v })} />
              {item.condition > 0 && <span className="text-sm font-semibold" style={{ color: BRAND }}>{conditionLabel(item.condition)}</span>}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

