          <textarea className="w-full border-2 border-gray-200 rounded-xl px-3 py-3 text-sm resize-none focus:outline-none" style={{ fontFamily: "Georgia, serif", minHeight: "160px" }} placeholder="e.g. Property presented in good overall condition throughout." value={comments} onChange={e => onChange(e.target.value)} />
